const episodes = $input.all().filter(item => item.json.id);

if (episodes.length === 0) {
  throw new Error('No draft episodes found. Run WF-04 first.');
}

const episode = episodes[0].json;
const hasAudio = !!episode.audio_url;

// Split script into chunks for TTS (if needed)
const script = episode.script || '';
const chunks = [];
const maxChunkLen = 500;
const sentences = script.split(/(?<=[.!?])\s+/);
let current = '';
for (const sentence of sentences) {
  if (current.length + sentence.length > maxChunkLen && current.length > 0) {
    chunks.push(current.trim());
    current = '';
  }
  current += sentence + ' ';
}
if (current.trim()) chunks.push(current.trim());

return [{
  json: {
    episode_id: episode.id,
    episode_title: episode.title,
    script: episode.script,
    audio_url: episode.audio_url || null,
    has_audio: hasAudio,
    chunks,
    chunk_count: chunks.length
  }
}];

// Fish Audio returns binary MP3 directly (responseFormat: file)
const episodeId = $('Clean Script Text').item.json.episode_id;
const episodeTitle = $('Clean Script Text').item.json.episode_title;
const fileName = 'episode-' + episodeId.substring(0, 8) + '.mp3';

// The binary data comes through from the HTTP Request
const binaryData = $input.first().binary;

if (!binaryData || !binaryData.data) {
  throw new Error('No binary audio data received from TTS');
}

return [{
  json: {
    episode_id: episodeId,
    episode_title: episodeTitle,
    file_name: fileName,
    audio_size: 0,
    tts_provider: 'fish'
  },
  binary: {
    audio: binaryData.data
  }
}];

