// Voice & Provider Selection
// Providers: 'hume' or 'fish'
// Voice modes: 'stock' or 'cloned'
const TTS_PROVIDER = 'fish';  // Switch to 'hume' when credits available
const VOICE_MODE = 'stock';    // Switch to 'cloned' when Brett's voice is ready

// Hume AI voices
const HUME_STOCK = '6b69954e-6c9a-4ade-ad03-f73e116e1eae';  // Australian Male
const HUME_CLONED = '095d952c-971d-42ce-beb8-381e5c94ab2b';  // Brett clone

// Fish Audio voices  
const FISH_STOCK = '802e3bc2b27e49c2995d23ef70e6ac89';  // Energetic Male
const FISH_CLONED = '15891e6b8799441da70f0016987a7885'; // Brett clone (needs Plus plan)

let voiceId, voiceLabel;
if (TTS_PROVIDER === 'hume') {
  voiceId = VOICE_MODE === 'cloned' ? HUME_CLONED : HUME_STOCK;
  voiceLabel = VOICE_MODE === 'cloned' ? "Brett (Hume)" : "Stock Australian (Hume)";
} else {
  voiceId = VOICE_MODE === 'cloned' ? FISH_CLONED : FISH_STOCK;
  voiceLabel = VOICE_MODE === 'cloned' ? "Brett (Fish)" : "Stock Male (Fish)";
}

const episode = $input.first().json;

return [{
  json: {
    ...episode,
    tts_provider: TTS_PROVIDER,
    voice_id: voiceId,
    voice_mode: VOICE_MODE,
    voice_label: voiceLabel
  }
}];

// After cloning, log the new voice ID
const response = $input.first().json;
const voiceId = response.id || response.voice_id || 'UNKNOWN';

return [{
  json: {
    voice_id: voiceId,
    message: 'Voice cloned! Update CLONED_VOICE_ID in Select Voice node with: ' + voiceId
  }
}];

