const script = $json.script || '';
const voiceId = $json.voice_id;

// Aggressively clean for safe JSON embedding
let cleanText = script
  .substring(0, 4000)
  .replace(/\[.*?\]/g, '')
  .replace(/["\\/]/g, '')
  .replace(/'/g, '')
  .replace(/\n/g, ' ')
  .replace(/\r/g, '')
  .replace(/\t/g, ' ')
  .replace(/[^a-zA-Z0-9 .,!?;:()\-]/g, '')
  .replace(/\s+/g, ' ')
  .trim();

return [{
  json: {
    clean_text: cleanText,
    voice_id: voiceId,
    tts_provider: $json.tts_provider,
    episode_id: $json.episode_id,
    episode_title: $json.episode_title,
    script: $json.script,
    voice_label: $json.voice_label
  }
}];

